+        grid.addColumn(Vet::firstName).setHeader("First Name");
+        grid.addColumn(Vet::lastName).setHeader("Last Name");
+        grid.addColumn(VetsView::specialtiesText).setHeader("Specialties");
+        grid.setItems(
+                query -> this.repository.findPage(query.getOffset(), query.getLimit()),
+                query -> this.repository.count());
+
+        setSizeFull();
+        add(grid);
+    }
+
+    private static String specialtiesText(Vet vet) {
+        return vet.specialties().isEmpty() ? "none" : String.join(", ", vet.specialties());
+    }
+}
